package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class BudgetActivity extends Activity{private EditText tech,sub,training,labor,admin,contingency,other,publicAid,investment;private Spinner type;private TextView result;private SharedPreferences p;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("budget",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Calculateur budgétaire",27,true));r.addView(Ui.text(this,"Contrôle interne des plafonds du programme.",13,false));type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"OBNL / coopérative","Entreprise privée à but lucratif"}));type.setSelection(p.getInt("type",0));r.addView(type);tech=f(r,"Technologie / outils","tech");sub=f(r,"Sous-traitance / consultation","sub");training=f(r,"Formation","training");labor=f(r,"Main-d’œuvre","labor");admin=f(r,"Administration","admin");contingency=f(r,"Contingence","contingency");other=f(r,"Autres dépenses admissibles","other");publicAid=f(r,"Autres aides publiques","other_public");investment=f(r,"Investissement du demandeur","applicant_investment");Button calc=Ui.primary(this,"Calculer et enregistrer");result=Ui.text(this,"",15,true);calc.setOnClickListener(v->calculate());r.addView(calc);r.addView(result);setContentView(Ui.wrap(this,r));calculate();}private EditText f(LinearLayout r,String h,String k){EditText e=Ui.field(this,h,p.getString(k,"0"));e.setInputType(2|8192);r.addView(e);return e;}private double n(EditText e){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return 0;}}private void calculate(){double t=n(tech)+n(sub)+n(training)+n(labor)+n(admin)+n(contingency)+n(other);boolean np=type.getSelectedItemPosition()==0;double rate=np?.90:.65,publicCap=np?.90:.75,contrib=np?.10:.25,investMin=np?.05:.10,otherAid=n(publicAid),inv=n(investment);double aid=Math.min(50000,Math.min(t*rate,Math.max(0,t*publicCap-otherAid)));double residual=Math.max(0,t-aid-otherAid);p.edit().putInt("type",type.getSelectedItemPosition()).putString("tech",tech.getText().toString()).putString("sub",sub.getText().toString()).putString("training",training.getText().toString()).putString("labor",labor.getText().toString()).putString("admin",admin.getText().toString()).putString("contingency",contingency.getText().toString()).putString("other",other.getText().toString()).putString("other_public",publicAid.getText().toString()).putString("applicant_investment",investment.getText().toString()).putFloat("total",(float)t).putFloat("aid",(float)aid).putFloat("required_contribution",(float)(t*contrib)).putFloat("required_investment",(float)(t*investMin)).apply();StringBuilder s=new StringBuilder(String.format(java.util.Locale.CANADA_FRENCH,"Budget : %.2f $\nAide théorique maximale : %.2f $\nAutres aides publiques : %.2f $\nContribution résiduelle : %.2f $\nContribution minimale : %.2f $\nInvestissement minimal : %.2f $\n",t,aid,otherAid,residual,t*contrib,t*investMin));if(t>0&&n(training)>t*.20)s.append("⚠ Formation > 20 %.\n");if(t>0&&n(admin)>t*.05)s.append("⚠ Administration > 5 %.\n");if(t>0&&n(contingency)>t*.10)s.append("⚠ Contingence > 10 %.\n");if(t>0&&residual<t*contrib-.01)s.append("⚠ Contribution du demandeur sous le minimum.\n");if(t>0&&inv<t*investMin-.01)s.append("⚠ Investissement saisi sous le minimum.\n");s.append(np?"OBNL/coop : aide et cumul public ≤ 90 %, contribution ≥ 10 %, investissement ≥ 5 %.":"Entreprise privée : aide ≤ 65 %, cumul public ≤ 75 %, contribution ≥ 25 %, investissement ≥ 10 %.");result.setText(s.toString());}}
